insert into public.mango_causes(key,guide,title,why,actions,urgent) values
('borer','drying-trees','{"en":"Stem borer"}'::jsonb,'{"en":"Holes and sawdust on the trunk point to it."}'::jsonb,'{"en":["Send a close photo of the holes today","Treat as advised by an expert, without delay"]}'::jsonb,true),
('dieback','drying-trees','{"en":"Dieback (fungal)"}'::jsonb,'{"en":"Branches dry from the tip downwards."}'::jsonb,'{"en":["Cut dry branches back to healthy wood and burn them","Apply a recommended paste on the cuts"]}'::jsonb,true),
('roots','drying-trees','{"en":"Root or soil trouble"}'::jsonb,'{"en":"When the whole tree turns pale the cause is often at the roots: waterlogging, hard soil or salt."}'::jsonb,'{"en":["Drain the basin if water stands","Send a photo of the soil near the trunk"]}'::jsonb,true),
('hopper','hopper-powdery-mildew','{"en":"Mango hopper"}'::jsonb,'{"en":"Sticky flowers and tiny jumping insects point to it."}'::jsonb,'{"en":["Act before full bloom, as recommended","Prune so air and light reach inside"]}'::jsonb,false),
('mildew','hopper-powdery-mildew','{"en":"Powdery mildew"}'::jsonb,'{"en":"White powder on flowers, especially with cold nights and dew."}'::jsonb,'{"en":["A recommended spray as panicles emerge, as per label","Check panicles daily, especially on dewy days"]}'::jsonb,false),
('flush','flowering','{"en":"Leaves instead of flowers"}'::jsonb,'{"en":"If watering continues in winter or the flush matures late, the tree makes leaves instead of flowers."}'::jsonb,'{"en":["No irrigation for bearing trees until flowering","Next year, prune and feed right after harvest"]}'::jsonb,false),
('waterOn','flowering','{"en":"Watering is on now"}'::jsonb,'{"en":"From October until flowering, bearing trees need mild water stress."}'::jsonb,'{"en":["Slowly stop watering the bearing trees","Keep watering young plants as needed"]}'::jsonb,false),
('reserves','alternate-bearing','{"en":"Tree reserves used up"}'::jsonb,'{"en":"After a heavy crop the tree makes less new growth, so it flowers less next year."}'::jsonb,'{"en":["Prune and give organic manure right after harvest","Protect the monsoon flush from pests"]}'::jsonb,false),
('water','fruit-drop','{"en":"Fruit drop from water stress or heat"}'::jsonb,'{"en":"When marble-size or bigger fruit drops, irregular water and hot winds are the usual cause."}'::jsonb,'{"en":["Light, regular irrigation once fruits are pea-sized","Mulch the basin"]}'::jsonb,false),
('natural','fruit-drop','{"en":"Early drop is natural"}'::jsonb,'{"en":"Heavy drop of mustard to pea-size fruit is normal."}'::jsonb,'{"en":["Keep hoppers and mildew in check at flowering","Do not spray insecticide on open flowers"]}'::jsonb,false),
('small','fruit-drop','{"en":"Too little water or food while fruit grows"}'::jsonb,'{"en":"Fruit stays small when water and nutrition run short as it grows."}'::jsonb,'{"en":["Regular irrigation from March to May","Feed according to a soil test"]}'::jsonb,false),
('micro','flowering','{"en":"Micronutrient shortage"}'::jsonb,'{"en":"Yellow new leaves can mean a shortage of zinc or iron."}'::jsonb,'{"en":["Get a leaf and soil test","Send a close photo of new leaves"]}'::jsonb,false),
('feed','alternate-bearing','{"en":"The tree is underfed"}'::jsonb,'{"en":"Old, lower leaves turning yellow often means the tree is short of food."}'::jsonb,'{"en":["Organic manure and recommended fertiliser after harvest","Get a soil test"]}'::jsonb,false),
('cultar','cultar','{"en":"Years of Cultar"}'::jsonb,'{"en":"Cultar every year can shorten shoots and weaken trees, especially when underfed."}'::jsonb,'{"en":["Do not raise the dose each year; ask an expert","Support the roots and soil"]}'::jsonb,false),
('soilLife','cultar','{"en":"Low soil life"}'::jsonb,'{"en":"Frequent fungicides, weedicides and insecticides can reduce useful soil microbes."}'::jsonb,'{"en":["Bring soil back to life with manure and biofertilisers","Avoid sprays you do not need"]}'::jsonb,false),
('healthy','flowering','{"en":"Orchard looks fine"}'::jsonb,'{"en":"You did not report a major problem."}'::jsonb,'{"en":["Keep up month-by-month care","Check daily at flowering"]}'::jsonb,false)
